import pandas as pd


def _is_null(v):
    return v is None or (isinstance(v, float) and pd.isna(v)) or pd.isna(v)


def _differs(a, b):
    an = _is_null(a)
    bn = _is_null(b)
    if an and bn:
        return False
    if an != bn:
        return True
    return a != b


def run(inputs: dict) -> dict:
    dim = inputs["DIM_PRODUCT"].copy()
    stg = inputs["STG_PRODUCT"].copy()

    # Preserve original dtypes for reconstruction
    cols = ["product_id", "category", "price_band", "eff_start_date",
            "eff_end_date", "is_current"]

    rows = dim.to_dict("records")

    # Map product_id -> index of current row (is_current == 1)
    current_idx = {}
    for i, r in enumerate(rows):
        if r.get("is_current") == 1 or r.get("is_current") == 1.0:
            current_idx[r["product_id"]] = i

    # Sort staged records by product_id, update_date ascending (stable)
    stg_sorted = stg.sort_values(
        by=["product_id", "update_date"], kind="mergesort"
    ).reset_index(drop=True)

    for s in stg_sorted.itertuples(index=False):
        pid = s.product_id
        s_category = s.category
        s_price_band = s.price_band
        s_update_date = s.update_date

        if pid not in current_idx:
            new_row = {
                "product_id": pid,
                "category": s_category,
                "price_band": s_price_band,
                "eff_start_date": s_update_date,
                "eff_end_date": None,
                "is_current": 1,
            }
            rows.append(new_row)
            current_idx[pid] = len(rows) - 1
        else:
            c = rows[current_idx[pid]]
            changed = (
                _differs(c.get("category"), s_category)
                or _differs(c.get("price_band"), s_price_band)
            )
            if changed:
                c["eff_end_date"] = s_update_date
                c["is_current"] = 0

                new_row = {
                    "product_id": pid,
                    "category": s_category,
                    "price_band": s_price_band,
                    "eff_start_date": s_update_date,
                    "eff_end_date": None,
                    "is_current": 1,
                }
                rows.append(new_row)
                current_idx[pid] = len(rows) - 1
            # else: no-op, unchanged record, no new version

    out = pd.DataFrame(rows, columns=cols)

    # Try to align dtypes with the original DIM_PRODUCT where possible
    for col in cols:
        if col in dim.columns:
            try:
                out[col] = out[col].astype(dim[col].dtype)
            except (TypeError, ValueError):
                pass

    return {"dim_product_out": out}
